use verus::prelude::*;

// Specification-enriched version of `to_lowercase`.
// We require no preconditions on the input vector.
// We ensure the output has the same length as the input,
// and that each character is converted to lowercase iff
// it is in the ASCII range 'A'..'Z', otherwise left unchanged.
#[requires(true)]
#[ensures(
    // Length is preserved
    result.len() == s.len()
    &&
    // For each index i in bounds, the output character is
    // exactly the lowercase conversion of the input character
    // when the input is 'A'..'Z', else it is unchanged.
    forall|i: int|
        0 <= i && i < s.len() as int ==>
            result[i as usize] ==
                if s[i as usize] >= 'A' && s[i as usize] <= 'Z' {
                    ((s[i as usize] as u8) + 32) as char
                } else {
                    s[i as usize]
                }
)]
fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    // We iterate over all characters in `s`.
    // For ASCII uppercase letters, we add 32 to convert to lowercase.
    for &c in s {
        if c >= 'A' && c <= 'Z' {
            // ASCII 'A'..'Z' -> 'a'..'z'
            result.push((c as u8 + 32) as char);
        } else {
            result.push(c);
        }
    }
    result
}